    await native('capture','tabs-narrow');
    $('tabs-filter').value='нет такого имени'; $('tabs-filter').dispatchEvent(new Event('input'));
    assert(document.querySelector('.tabs-no-results'),'Search explains empty results');
    document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));
