    assert(activeName()===overflowNames[0] && activeVisible(),'Ctrl+Tab switches and reveals the next tab');
    await key('Digit9'); assert(activeName()===overflowNames.at(-1) && activeVisible(),'Ctrl+9 reveals the last tab');
    await native('resize',{width:1920,height:900}); await wait(250);
    assert(activeVisible() && $('tab-strip').classList.contains('is-overflow'),'Wide windows retain overflow behavior when necessary');
    $('theme').click(); $('tabs-menu-toggle').click(); await wait(100); await native('capture','tabs-dark');
    document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true})); $('theme').click();
    while(count()>1) await close();
    await native('resize',{width:1120,height:820}); await wait(200);
    assert(!$('tab-strip').classList.contains('is-overflow') && Math.abs(topCenter('open')-plusCenter)<1,'Overflow controls disappear when the remaining tab fits, without moving plus vertically');
    await pass('33 tabs: stable header alignment, arrows, wheel, searchable list, keyboard navigation, narrow/wide windows and dark theme');

    await open('Другой.md', 'Заметка.md'); assert(count() === 2, 'Multiple open and deduplication');
    await setText('# Изменено\n\n**Жирный**');
    await poll(() => document.querySelector('#document strong')?.textContent === 'Жирный', 'live preview');
    assert(document.querySelector('.tab-item.active').classList.contains('dirty'), 'Dirty indicator');
    await key('KeyZ'); assert($('source').value.includes('Простой текст.'), 'Undo');
    await key('KeyZ', true); assert($('source').value.includes('**Жирный**'), 'Redo');
    await key('KeyS'); assert((await native('read', 'Заметка.md')) === '# Изменено\r\n\r\n**Жирный**', 'Save preserves CRLF');
    assert(!document.querySelector('.tab-item.active').classList.contains('dirty'), 'Clean after save');
    await pass('Tabs, live editing, undo/redo, Ctrl+S and preserved line endings');

    await setText('# Черновик');
    await native('configure', { answer: 2 }); document.querySelector('.tab-item.active .tab-close').click(); await ready();
    assert(count() === 2 && $('source').value === '# Черновик', 'Cancel dirty close preserves draft');
    await native('configure', { answer: 1 }); $('reload').click(); await ready(); assert($('source').value.includes('Изменено'), 'Discard and reload');
    await setText('# Моя версия'); await native('write', { name: 'Заметка.md', text: '# Внешняя версия' });
    await native('configure', { answer: 2 }); await key('KeyS'); assert((await native('read', 'Заметка.md')) === '# Внешняя версия', 'Conflict cancel preserves external data');
    await native('configure', { answer: 0, save: 'Копия.md' }); await key('KeyS');
    assert((await native('read', 'Копия.md')) === '# Моя версия' && activeName() === 'Копия.md', 'Save As conflict copy');
    await pass('Unsaved prompts, reload/discard, external file conflict and Save As');

    await open('legacy.md'); await setText('# Привет 🙂'); await key('KeyS');
